import { VxeUI } from "@vxe-ui/core";
import VxeCarouselComponent from "./src/carousel";
import { dynamicApp } from "../dynamics";
const VxeCarousel = Object.assign({}, VxeCarouselComponent, {
  install(app) {
    app.component(VxeCarouselComponent.name, VxeCarouselComponent);
  }
});
dynamicApp.use(VxeCarousel);
VxeUI.component(VxeCarouselComponent);
const Carousel = VxeCarousel;
var carousel_default = VxeCarousel;
export {
  Carousel,
  VxeCarousel,
  carousel_default as default
};
