import { VxeUI } from "@vxe-ui/core";
import VxeBreadcrumbComponent from "./src/breadcrumb";
import { dynamicApp } from "../dynamics";
const VxeBreadcrumb = Object.assign({}, VxeBreadcrumbComponent, {
  install(app) {
    app.component(VxeBreadcrumbComponent.name, VxeBreadcrumbComponent);
  }
});
dynamicApp.use(VxeBreadcrumb);
VxeUI.component(VxeBreadcrumbComponent);
const Breadcrumb = VxeBreadcrumb;
var breadcrumb_default = VxeBreadcrumb;
export {
  Breadcrumb,
  VxeBreadcrumb,
  breadcrumb_default as default
};
