import { VxeUI } from "@vxe-ui/core";
import VxeCountdownComponent from "./src/countdown";
import { dynamicApp } from "../dynamics";
const VxeCountdown = Object.assign({}, VxeCountdownComponent, {
  install(app) {
    app.component(VxeCountdownComponent.name, VxeCountdownComponent);
  }
});
dynamicApp.use(VxeCountdown);
VxeUI.component(VxeCountdownComponent);
const Countdown = VxeCountdown;
var countdown_default = VxeCountdown;
export {
  Countdown,
  VxeCountdown,
  countdown_default as default
};
